{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://orbit.local/contracts/check-result.schema.json",
  "title": "Orbit independent check result",
  "description": "Final JSON object returned by an independent check or adjudication run (Orbit 1, contracts/task-runtime.md). Strings are expected to be non-empty and next_check_seconds is a positive integer, even where JSON Schema alone cannot express it inside Codex structured output. delivery is the checker's structured delivery-readiness judgment, separate from verdict and findings: ready=true requires the actual deliverable to be inspectable at check time (the fixed artifact, or the Root's actually delivered final answer visible in the program record), never a Root claim or a verdict alone. coverage records the independent checker enumeration and evidence per requirement. Missing coverage is unknown, and cannot release a new task for completion.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "verdict",
    "reason",
    "findings",
    "resolved_ids",
    "next_check_seconds",
    "delivery"
  ],
  "properties": {
    "verdict": {
      "enum": [
        "continue",
        "correct",
        "pause",
        "complete",
        "needs_user"
      ]
    },
    "reason": {
      "type": "string"
    },
    "findings": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "id",
          "requirement",
          "evidence",
          "action"
        ],
        "properties": {
          "id": {
            "type": "string"
          },
          "requirement": {
            "type": "string"
          },
          "evidence": {
            "type": "string"
          },
          "action": {
            "type": "string"
          }
        }
      }
    },
    "resolved_ids": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "next_check_seconds": {
      "type": "integer"
    },
    "delivery": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "ready",
        "reason"
      ],
      "properties": {
        "ready": {
          "type": "boolean"
        },
        "reason": {
          "type": "string"
        }
      }
    },
    "coverage": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "complete",
        "items"
      ],
      "properties": {
        "complete": {
          "type": "boolean"
        },
        "items": {
          "type": "array",
          "minItems": 1,
          "maxItems": 64,
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "requirement",
              "status",
              "evidence"
            ],
            "properties": {
              "requirement": {
                "type": "string",
                "minLength": 1,
                "maxLength": 1000,
                "description": "One enumerated requirement, kept verbatim. The bound is a representation bound (a long requirement sentence must survive unmodified), not a relaxation of acceptance: missing, duplicate or oversized items are still refused and nothing is truncated."
              },
              "status": {
                "enum": [
                  "verified",
                  "unverified"
                ]
              },
              "evidence": {
                "type": "string",
                "maxLength": 1000
              },
              "scope": {
                "enum": [
                  "delivery",
                  "lifecycle"
                ],
                "description": "Delivery requirements, including actual tests, must be verified; future final-check, closing-report and confirmed-stop obligations remain listed and are verified by runtime lifecycle gates. Missing scope keeps the earlier delivery-only interpretation."
              }
            }
          }
        }
      }
    }
  }
}

