        input_digest_status: binding?.input_digest ? 'ok' : 'unknown',
        projection_bytes: Buffer.byteLength(projection.text), projection_sha256: `sha256:${sha}`,
        delivered_claim: 'first append of this projection version under this actual model to a request payload in this process; ' +
